pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Favor bins with more space available
    if post_residual < 50.0 {
        score -= 1.0;
    }

    // Penalize bins that are almost full
    if bin_residual < 20.0 {
        score += 1.0;
    }

    // Favor bins that can fit the next item exactly or with minimal waste
    if post_residual == next_item_size {
        score -= 0.5;
    } else if post_residual > next_item_size && post_residual - next_item_size < mean_residual / open_bins_count {
        score -= 0.25;
    }

    // Penalize bins that are close to the mean residual, as they may lead to waste
    if post_residual.abs() < mean_residual / open_bins_count {
        score += 0.1;
    }

    score
}

