pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;

    // Non-linear conditional based on bin capacity and residual
    if bin_capacity - bin_residual < 50 {
        score += (bin_capacity - bin_residual) as f64 / 75.0;
    } else {
        score -= (bin_capacity - bin_residual) as f64 / 190.0;
    }

    // Conditional based on post-residual
    if post_residual > 35 {
        score -= (post_residual - 35) as f64 / 12.0;
    } else {
        score += (35 - post_residual) as f64 / 25.0;
    }

    // Reward for exact item size matching bin residual
    if item_size == bin_residual {
        score += 4.5;
    }

    // Penalize for next item size that fits in the bin but is not optimal
    if next_item_size > 0 && next_item_size <= bin_capacity - bin_residual {
        score -= (next_item_size as f64).ln() * 1.2;
    }

    // Time horizon adjustment
    let time_horizon = step_index as f64 / total_items as f64;
    if time_horizon < 0.5 {
        score += (1.0 - time_horizon) * 3.0;
    } else {
        score -= (time_horizon - 0.5) * 3.0;
    }

    // Penalty for no fitting bins
    if fitting_bins_count == 0 {
        score -= 20.0;
    }

    // Penalize open bins count
    score -= open_bins_count as f64 * 0.35;

    // Additional penalty to incentivize compaction
    score -= (bin_capacity - bin_residual) as f64 / 100.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;

    // Combine multiple factors for better compaction
    score += (bin_capacity - bin_residual) as f64 * 0.18;
    if post_residual > mean_residual {
        score -= (post_residual - mean_residual) as f64 / 12.0;
    } else {
        score += (mean_residual - post_residual) as f64 / 25.0;
    }
    if item_size == bin_residual {
        score += 6.0;
    }
    if next_item_size > 0 && next_item_size <= bin_capacity - bin_residual {
        score -= (next_item_size as f64).ln() * 1.2;
    }

    // Time-based adjustment
    let time_horizon = step_index as f64 / total_items as f64;
    if time_horizon < 0.5 {
        score += (1.0 - time_horizon) * 3.0;
    } else {
        score -= (time_horizon - 0.5) * 2.5;
    }

    // Penalize empty bins
    if fitting_bins_count == 0 {
        score -= 40.0;
    }

    // Penalties for open bins
    score -= open_bins_count as f64 * 0.35;

    // Reward for bins with sufficient capacity utilization
    if bin_capacity - bin_residual > bin_capacity / 2 {
        score += (bin_capacity - bin_residual) as f64 / 170.0;
    }

    // Penalize large post-residuals
    if post_residual > bin_capacity / 3 {
        score -= (post_residual - bin_capacity / 3) as f64 / 20.0;
    } else {
        score += (bin_capacity / 3 - post_residual) as f64 / 35.0;
    }

    // Reward for low open bins count
    if open_bins_count < total_items / 2 {
        score += (total_items / 2 - open_bins_count) as f64 * 0.18;
    } else {
        score -= (open_bins_count - total_items / 2) as f64 * 0.25;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;

    // Enhanced adaptive weight for bin capacity
    if bin_capacity - bin_residual < 50 {
        score += (bin_capacity - bin_residual) as f64 / 100.0;
    } else if bin_capacity - bin_residual < 200 {
        score += (bin_capacity - bin_residual) as f64 / 200.0;
    }

    // Modified penalty for large post-residuals
    if post_residual > 50 {
        score -= (post_residual - 45) as f64 / 15.0;
    } else {
        score += (45 - post_residual) as f64 / 25.0;
    }

    // Enhanced reward for exact fits
    if item_size == bin_residual {
        score += 5.0;
    } else if item_size <= bin_residual {
        score += (bin_residual - item_size) as f64 / 100.0;
    }

    // Adjusted penalty for next item fitting opportunities
    if next_item_size > 0 && next_item_size <= bin_capacity - bin_residual {
        score -= ((next_item_size as f64).ln() / 2.0).max(1.0);
    }

    // Time-based scoring with refined thresholds and bonus
    let time_horizon = step_index as f64 / total_items as f64;
    if time_horizon < 0.3 {
        score += (1.0 - time_horizon) * 5.0;
    } else if time_horizon > 0.7 {
        score -= (time_horizon - 0.7) * 5.0;
    }

    // Reduced penalty for open bins with additional bonus
    score -= open_bins_count as f64 * 0.1;
    if open_bins_count == 1 {
        score += 2.0;
    }

    // Adjusted penalty for fitting bins count with additional bonus
    if fitting_bins_count == 0 {
        score -= 10.0;
    } else if fitting_bins_count == 1 {
        score += 3.0;
    }

    score
}
